"""Demo 1: Exhaustive verification of the quasifield/nearfield axioms of the
Dickson product on GF(9). Confirms two-sided unit, absorbing zero, right
distributivity, unique two-sided division, the planar (Veblen) axiom, and
associativity -- everything needed for a nearfield."""
from __future__ import annotations
from typing import List, Tuple

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
ZERO: Elem = (0, 0)
ONE: Elem = (1, 0)


def add(x: Elem, y: Elem) -> Elem:
    return ((x[0] + y[0]) % 3, (x[1] + y[1]) % 3)


def sub(x: Elem, y: Elem) -> Elem:
    return ((x[0] - y[0]) % 3, (x[1] - y[1]) % 3)


def gf9_mul(x: Elem, y: Elem) -> Elem:
    a, b = x
    c, d = y
    return ((a * c + 2 * b * d) % 3, (a * d + b * c) % 3)


def frob(x: Elem) -> Elem:
    return (x[0], (2 * x[1]) % 3)


def is_sq(b: Elem) -> bool:
    return any(c != ZERO and gf9_mul(c, c) == b for c in ELEMENTS)


def dmul(a: Elem, b: Elem) -> Elem:
    return gf9_mul(a, b) if (b == ZERO or is_sq(b)) else gf9_mul(frob(a), b)


def is_bijection(images: List[Elem]) -> bool:
    return sorted(set(images)) == sorted(ELEMENTS)


def main() -> None:
    ok_unit = all(dmul(x, ONE) == x and dmul(ONE, x) == x for x in ELEMENTS)
    ok_zero = all(dmul(x, ZERO) == ZERO and dmul(ZERO, x) == ZERO for x in ELEMENTS)
    ok_rdist = all(
        dmul(add(a, b), c) == add(dmul(a, c), dmul(b, c))
        for a in ELEMENTS for b in ELEMENTS for c in ELEMENTS
    )
    ok_ldiv = all(is_bijection([dmul(a, x) for x in ELEMENTS])
                  for a in ELEMENTS if a != ZERO)
    ok_rdiv = all(is_bijection([dmul(x, a) for x in ELEMENTS])
                  for a in ELEMENTS if a != ZERO)
    ok_planar = all(
        is_bijection([sub(dmul(x, a), dmul(x, b)) for x in ELEMENTS])
        for a in ELEMENTS for b in ELEMENTS if a != b
    )
    ok_assoc = all(
        dmul(dmul(a, b), c) == dmul(a, dmul(b, c))
        for a in ELEMENTS for b in ELEMENTS for c in ELEMENTS
    )
    for name, ok in [
        ("two-sided unit", ok_unit), ("absorbing zero", ok_zero),
        ("right distributivity", ok_rdist), ("unique left division", ok_ldiv),
        ("unique right division", ok_rdiv), ("planar (Veblen) axiom", ok_planar),
        ("associativity (nearfield)", ok_assoc),
    ]:
        print(f"[{'PASS' if ok else 'FAIL'}] {name}")


if __name__ == "__main__":
    main()

"""Demo 2: The algebraic obstruction to Desargues. Enumerates every failure of
the left distributive law and of commutativity in the Dickson nearfield of
order 9, and displays the canonical witness a=alpha, b=alpha, c=1 in which the
sum of two squares (alpha and 1) lands on the non-square 1+alpha and flips the
branch of the multiplication."""
from __future__ import annotations
from typing import List, Tuple

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
ZERO: Elem = (0, 0)


def add(x: Elem, y: Elem) -> Elem:
    return ((x[0] + y[0]) % 3, (x[1] + y[1]) % 3)


def gf9_mul(x: Elem, y: Elem) -> Elem:
    a, b = x
    c, d = y
    return ((a * c + 2 * b * d) % 3, (a * d + b * c) % 3)


def frob(x: Elem) -> Elem:
    return (x[0], (2 * x[1]) % 3)


def is_sq(b: Elem) -> bool:
    return any(c != ZERO and gf9_mul(c, c) == b for c in ELEMENTS)


def dmul(a: Elem, b: Elem) -> Elem:
    return gf9_mul(a, b) if (b == ZERO or is_sq(b)) else gf9_mul(frob(a), b)


def fmt(x: Elem) -> str:
    a, b = x
    if b == 0:
        return str(a)
    if a == 0:
        return ("" if b == 1 else str(b)) + "a"
    return f"{a}+{'' if b == 1 else b}a"


def main() -> None:
    ld = [(a, b, c) for a in ELEMENTS for b in ELEMENTS for c in ELEMENTS
          if dmul(a, add(b, c)) != add(dmul(a, b), dmul(a, c))]
    nc = [(a, b) for a in ELEMENTS for b in ELEMENTS if dmul(a, b) != dmul(b, a)]
    print(f"left-distributivity failures : {len(ld)} of 729 triples")
    print(f"commutativity failures       : {len(nc)} of 81 pairs")

    a, b, c = (0, 1), (0, 1), (1, 0)  # alpha, alpha, 1
    lhs, rhs = dmul(a, add(b, c)), add(dmul(a, b), dmul(a, c))
    print("\nCanonical left-distributivity witness:")
    print(f"  a={fmt(a)}, b={fmt(b)}, c={fmt(c)};  b+c = {fmt(add(b, c))} "
          f"(a non-square)")
    print(f"  a*(b+c)   = {fmt(lhs)}")
    print(f"  a*b + a*c = {fmt(rhs)}")
    print(f"  equal? {lhs == rhs}  -> left distributivity FAILS")


if __name__ == "__main__":
    main()

"""Demo 3: The coordinatized non-Desarguesian affine plane of order 9.
Builds the 81 points and 90 lines from the Dickson product and verifies the
affine incidence axioms: any two distinct points lie on a unique line,
Playfair's parallel axiom holds, every line has 9 points, and every point lies
on 10 lines."""
from __future__ import annotations
from typing import List, Tuple

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
ZERO: Elem = (0, 0)
Point = Tuple[Elem, Elem]
Line = Tuple


def add(x: Elem, y: Elem) -> Elem:
    return ((x[0] + y[0]) % 3, (x[1] + y[1]) % 3)


def gf9_mul(x: Elem, y: Elem) -> Elem:
    a, b = x
    c, d = y
    return ((a * c + 2 * b * d) % 3, (a * d + b * c) % 3)


def frob(x: Elem) -> Elem:
    return (x[0], (2 * x[1]) % 3)


def is_sq(b: Elem) -> bool:
    return any(c != ZERO and gf9_mul(c, c) == b for c in ELEMENTS)


def dmul(a: Elem, b: Elem) -> Elem:
    return gf9_mul(a, b) if (b == ZERO or is_sq(b)) else gf9_mul(frob(a), b)


POINTS: List[Point] = [(x, y) for x in ELEMENTS for y in ELEMENTS]
LINES: List[Line] = [("ord", m, b) for m in ELEMENTS for b in ELEMENTS] + \
                    [("ver", c) for c in ELEMENTS]


def on_line(p: Point, L: Line) -> bool:
    x, y = p
    if L[0] == "ord":
        return y == add(dmul(x, L[1]), L[2])
    return x == L[1]


def parallel(L1: Line, L2: Line) -> bool:
    if L1[0] == "ord" and L2[0] == "ord":
        return L1[1] == L2[1]
    return L1[0] == "ver" and L2[0] == "ver"


def main() -> None:
