from __future__ import annotations
from typing import List, Tuple

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
ZERO: Elem = (0, 0)


def gf9_mul(x: Elem, y: Elem) -> Elem:
    """Field multiplication in GF(9) = GF(3)[alpha], alpha^2 = 2."""
    a, b = x
    c, d = y
    return ((a * c + 2 * b * d) % 3, (a * d + b * c) % 3)


def frob(x: Elem) -> Elem:
    """Frobenius sigma(a + b*alpha) = a - b*alpha (= x^3)."""
    return (x[0], (2 * x[1]) % 3)


def is_nonzero_square(b: Elem) -> bool:
    """Decide whether b is a nonzero square by scanning c*c over c != 0."""
    return any(c != ZERO and gf9_mul(c, c) == b for c in ELEMENTS)


def dickson_mul(a: Elem, b: Elem) -> Elem:
    """Dickson product: twist the LEFT factor by Frobenius exactly when the
    RIGHT factor is a non-square; otherwise multiply as in the field."""
    if b == ZERO or is_nonzero_square(b):
        return gf9_mul(a, b)
    return gf9_mul(frob(a), b)

from __future__ import annotations
from typing import Callable, List, Tuple

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
BinOp = Callable[[Elem, Elem], Elem]


def add(x: Elem, y: Elem) -> Elem:
    return ((x[0] + y[0]) % 3, (x[1] + y[1]) % 3)


def sub(x: Elem, y: Elem) -> Elem:
    return ((x[0] - y[0]) % 3, (x[1] - y[1]) % 3)


def is_bijection(images: List[Elem]) -> bool:
    """A finite self-map is bijective iff its image set is the whole domain."""
    return sorted(set(images)) == sorted(ELEMENTS)


def verify_quasifield(mul: BinOp, one: Elem, zero: Elem) -> dict:
    """Exhaustively check all quasifield axioms for `mul`. Returns a dict of
    axiom-name -> bool. Complexity O(|Q|^3) for the ternary laws."""
    result = {}
    result["unit"] = all(mul(x, one) == x and mul(one, x) == x for x in ELEMENTS)
    result["zero"] = all(mul(x, zero) == zero and mul(zero, x) == zero
                         for x in ELEMENTS)
    result["right_distrib"] = all(
        mul(add(a, b), c) == add(mul(a, c), mul(b, c))
        for a in ELEMENTS for b in ELEMENTS for c in ELEMENTS
    )
    result["left_division"] = all(
        is_bijection([mul(a, x) for x in ELEMENTS])
        for a in ELEMENTS if a != zero
    )
    result["right_division"] = all(
        is_bijection([mul(x, a) for x in ELEMENTS])
        for a in ELEMENTS if a != zero
    )
    result["planar"] = all(
        is_bijection([sub(mul(x, a), mul(x, b)) for x in ELEMENTS])
        for a in ELEMENTS for b in ELEMENTS if a != b
    )
    result["associative"] = all(
        mul(mul(a, b), c) == mul(a, mul(b, c))
        for a in ELEMENTS for b in ELEMENTS for c in ELEMENTS
    )
    result["commutative"] = all(mul(a, b) == mul(b, a)
                                for a in ELEMENTS for b in ELEMENTS)
    result["left_distrib"] = all(
        mul(a, add(b, c)) == add(mul(a, b), mul(a, c))
        for a in ELEMENTS for b in ELEMENTS for c in ELEMENTS
    )
    return result

