from __future__ import annotations
from typing import Callable, List, Optional, Tuple

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
Point = Tuple[Elem, Elem]
Line = Tuple  # ("ord", m, b) or ("ver", c)
BinOp = Callable[[Elem, Elem], Elem]


def add(x: Elem, y: Elem) -> Elem:
    return ((x[0] + y[0]) % 3, (x[1] + y[1]) % 3)


def sub(x: Elem, y: Elem) -> Elem:
    return ((x[0] - y[0]) % 3, (x[1] - y[1]) % 3)


def solve_left(mul: BinOp, a: Elem, c: Elem) -> Optional[Elem]:
    """Unique left division: the x with a*x = c (a != 0), found by search."""
    for x in ELEMENTS:
        if mul(a, x) == c:
            return x
    return None


def line_through(mul: BinOp, p: Point, q: Point) -> Line:
    """Return the unique line through distinct points p, q.

    If the x-coordinates agree, the join is the vertical line x = x1.
    Otherwise the slope m is obtained by unique left division from the
    equation (x1 - x2) * m = y1 - y2, and the intercept is b = y1 - x1*m.
    """
    (x1, y1), (x2, y2) = p, q
    if x1 == x2:
        return ("ver", x1)
    m = solve_left(mul, sub(x1, x2), sub(y1, y2))
    assert m is not None
    b = sub(y1, mul(x1, m))
    return ("ord", m, b)

