"""Visualization 1: Side-by-side multiplication tables of the ordinary GF(9)
field product and the twisted Dickson product, with the twisted (non-square
right-factor) columns highlighted. Saves 'dickson_tables.png'."""
from __future__ import annotations
from typing import List, Tuple
import matplotlib.pyplot as plt
import numpy as np

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
ZERO: Elem = (0, 0)
IDX = {e: i for i, e in enumerate(ELEMENTS)}
LABELS = ["0", "1", "2", "a", "1+a", "2+a", "2a", "1+2a", "2+2a"]


def gf9_mul(x: Elem, y: Elem) -> Elem:
    a, b = x
    c, d = y
    return ((a * c + 2 * b * d) % 3, (a * d + b * c) % 3)


def frob(x: Elem) -> Elem:
    return (x[0], (2 * x[1]) % 3)


def is_sq(b: Elem) -> bool:
    return any(c != ZERO and gf9_mul(c, c) == b for c in ELEMENTS)


def dmul(a: Elem, b: Elem) -> Elem:
    return gf9_mul(a, b) if (b == ZERO or is_sq(b)) else gf9_mul(frob(a), b)


def table(mul) -> np.ndarray:
    return np.array([[IDX[mul(a, b)] for b in ELEMENTS] for a in ELEMENTS])


def main() -> None:
    field_t, dickson_t = table(gf9_mul), table(dmul)
    fig, axes = plt.subplots(1, 2, figsize=(14, 6))
    for ax, T, title in [(axes[0], field_t, "GF(9) field product"),
                         (axes[1], dickson_t, "Dickson product")]:
        ax.imshow(T, cmap="viridis")
        ax.set_xticks(range(9)); ax.set_yticks(range(9))
        ax.set_xticklabels(LABELS, rotation=45); ax.set_yticklabels(LABELS)
        ax.set_title(title); ax.set_xlabel("right factor b"); ax.set_ylabel("left factor a")
        for i in range(9):
            for j in range(9):
                ax.text(j, i, LABELS[T[i, j]], ha="center", va="center",
                        color="w", fontsize=7)
    # highlight non-square columns in the Dickson table
    for j, b in enumerate(ELEMENTS):
        if b != ZERO and not is_sq(b):
            axes[1].add_patch(plt.Rectangle((j - 0.5, -0.5), 1, 9, fill=False,
                                            edgecolor="red", lw=2))
    fig.suptitle("Twisting GF(9): red columns (non-square right factor) apply Frobenius")
    plt.tight_layout()
    plt.savefig("dickson_tables.png", dpi=150)
    print("wrote dickson_tables.png")


if __name__ == "__main__":
    main()

