from __future__ import annotations
from typing import List, Tuple
import matplotlib.pyplot as plt

Elem = Tuple[int, int]
ELEMENTS: List[Elem] = [(a, b) for a in range(3) for b in range(3)]
ZERO: Elem = (0, 0)


def gf9_mul(x: Elem, y: Elem) -> Elem:
    a, b = x
    c, d = y
    return ((a * c + 2 * b * d) % 3, (a * d + b * c) % 3)


def is_sq(b: Elem) -> bool:
    return any(c != ZERO and gf9_mul(c, c) == b for c in ELEMENTS)


def fmt(x: Elem) -> str:
    a, b = x
    if b == 0:
        return str(a)
    if a == 0:
        return ("" if b == 1 else str(b)) + "α"
    return f"{a}+{'' if b == 1 else b}α"


def main() -> None:
    fig, ax = plt.subplots(figsize=(6, 6))
    for (a, b) in ELEMENTS:
        if (a, b) == ZERO:
            color, tag = "#cccccc", "0"
        elif is_sq((a, b)):
            color, tag = "#4caf50", "square"
        else:
            color, tag = "#e53935", "non-square"
        ax.add_patch(plt.Rectangle((a - 0.5, b - 0.5), 1, 1, color=color,
                                   alpha=0.6))
        ax.text(a, b + 0.18, fmt((a, b)), ha="center", fontsize=12, weight="bold")
        ax.text(a, b - 0.28, tag, ha="center", fontsize=8)
    ax.set_xlim(-0.6, 2.6); ax.set_ylim(-0.6, 2.6)
    ax.set_xticks([0, 1, 2]); ax.set_yticks([0, 1, 2])
    ax.set_xlabel("real part a"); ax.set_ylabel("alpha part b")
    ax.set_title("GF(9): squares (green, on axes) vs non-squares (red)")
    ax.set_aspect("equal")
